// 1. Severity ranking and colors
const severityOrder = { Critical: 0, High: 1, Medium: 2, Low: 3 };
const badge = {
  Critical: { emoji: '🔴', color: '#d93025', bg: '#fce8e6' },
  High:     { emoji: '🟠', color: '#e8710a', bg: '#fef0e0' },
  Medium:   { emoji: '🟡', color: '#b58100', bg: '#fef7d6' },
  Low:      { emoji: '🟢', color: '#188038', bg: '#e6f4ea' },
};

// 2. Get articles and sort: most severe first
const articles = $input.all()
  .map((item) => item.json)
  .sort((x, y) =>
    (severityOrder[x.output?.severity] ?? 9) - (severityOrder[y.output?.severity] ?? 9)
  );

// 3. Count stories per severity for the header line
const counts = {};
for (const a of articles) {
  const s = a.output?.severity || 'Unknown';
  counts[s] = (counts[s] || 0) + 1;
}
const countLine = Object.keys(severityOrder)
  .filter((s) => counts[s])
  .map((s) => `${badge[s].emoji} ${counts[s]} ${s}`)
  .join(' &nbsp;·&nbsp; ');

// 4. Build one card per article
const cards = articles.map((a) => {
  const ai = a.output || {};
  const b = badge[ai.severity] || { emoji: '⚪', color: '#5f6368', bg: '#f1f3f4' };
  const date = new Date(a.isoDate || a.pubDate).toDateString();
  const image = a.enclosure?.url
    ? `<img src="${a.enclosure.url}" style="width:100%;max-width:560px;border-radius:8px;margin-bottom:10px">`
    : '';

  return `
  <div style="border:1px solid #e0e0e0;border-left:5px solid ${b.color};border-radius:8px;padding:16px;margin-bottom:18px">
    ${image}
    <span style="background:${b.bg};color:${b.color};font-weight:bold;font-size:12px;padding:3px 10px;border-radius:12px">${b.emoji} ${ai.severity || 'Unrated'}</span>
    <span style="background:#f1f3f4;color:#3c4043;font-size:12px;padding:3px 10px;border-radius:12px;margin-left:6px">${ai.category || 'Other'}</span>
    <h3 style="margin:10px 0 6px;font-size:17px">
      <a href="${a.link}" style="color:#1a0dab;text-decoration:none">${a.title}</a>
    </h3>
    <p style="margin:0 0 6px;color:#202124">💡 ${ai.summary || ''}</p>
    <small style="color:#70757a">${date}</small>
  </div>`;
});

// 5. Put the full email together
const html = `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto">
  <h2 style="margin-bottom:4px">🛡️ AI Cybersecurity Briefing</h2>
  <p style="color:#5f6368;margin-top:0">${new Date().toDateString()} &nbsp;|&nbsp; ${countLine}</p>
  ${cards.join('')}
  <p style="color:#9aa0a6;font-size:12px;text-align:center">Analyzed by Gemini · Automated with n8n</p>
</div>`;

return [{
  json: {
    subject: `🛡️ Cyber Briefing — ${new Date().toDateString()}${counts.Critical ? ` · ${counts.Critical} Critical` : ''}`,
    html,
  },
}];
